using ETulong;using ETulongData;using Microsoft.EntityFrameworkCore;using System.Text.Json.Serialization;
var builder=WebApplication.CreateBuilder(args);builder.WebHost.ConfigureKestrel(o=>o.Limits.MaxRequestBodySize=3*1024*1024);builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow);builder.Services.Configure<Microsoft.AspNetCore.Routing.RouteHandlerOptions>(o=>o.ThrowOnBadRequest=true);
var connection=Environment.GetEnvironmentVariable("ETULONG_DB")??builder.Configuration.GetConnectionString("ETulong")??throw new InvalidOperationException("Set ETULONG_DB using a dedicated PostgreSQL database.");builder.Services.AddDbContextFactory<DeskDb>(o=>o.UseNpgsql(connection));var fixedDate=Environment.GetEnvironmentVariable("ETULONG_TEST_DATE");if(builder.Environment.IsDevelopment()&&fixedDate is not null)builder.Services.AddSingleton<IClock>(new FixedClock(DateOnly.ParseExact(fixedDate,"yyyy-MM-dd")));else builder.Services.AddSingleton<IClock,ManilaClock>();
if(builder.Environment.IsDevelopment()&&Environment.GetEnvironmentVariable("ETULONG_FAULT_AFTER_WRITE")=="1"){if(!new Npgsql.NpgsqlConnectionStringBuilder(connection).Database!.EndsWith("_test"))throw new InvalidOperationException("Fault injection requires an owned disposable _test database.");builder.Services.AddSingleton<IWriteFault,WriteFault>();}else builder.Services.AddSingleton<IWriteFault,NoWriteFault>();builder.Services.AddScoped<IDeskStore,DeskStore>();builder.Services.AddScoped<DeskService>();var app=builder.Build();
app.Use(async(ctx,next)=>{try{await next();}catch(DeskException e){ctx.Response.StatusCode=e.Status;await ctx.Response.WriteAsJsonAsync(new{code=e.Code,message=e.Message});}catch(BadHttpRequestException){ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{code="validation",message="Check request fields, values and image size."});}catch(Exception ex){app.Logger.LogError(ex,"Request failed");ctx.Response.StatusCode=500;await ctx.Response.WriteAsJsonAsync(new{code="server",message="The service could not complete this request. Check server/database availability and refresh before retrying."});}});
app.UseStatusCodePages(async c=>await c.HttpContext.Response.WriteAsJsonAsync(new{code="http",message="The route or HTTP method is not available."}));
int Actor(HttpRequest r)=>int.TryParse(r.Headers["X-Demo-Staff"],out var id)?id:throw new DeskException(403,"actor","Select a demonstration operator before saving.");
app.MapGet("/health",async(IDbContextFactory<DeskDb> f)=>{await using var d=await f.CreateDbContextAsync();return await d.Database.CanConnectAsync()?Results.Ok(new{status="ready"}):Results.StatusCode(503);});
app.MapGet("/api/reference",(DeskService s)=>s.Reference());app.MapGet("/api/cases",(DeskService s,string? search,string? status,int? page,int? size)=>s.Cases(search,status,page??1,size??25));app.MapGet("/api/cases/{id}",(DeskService s,int id)=>s.Detail(id));app.MapGet("/api/documents/{id}/image",async(DeskService s,int id)=>{var im=await s.Image(id);return Results.File(im.Content,im.ContentType);});
app.MapPost("/api/cases",async(DeskService s,DraftInput x,HttpRequest r)=>{var c=await s.Draft(x,Actor(r));return Results.Created($"/api/cases/{c.Id}",c);});
app.MapPost("/api/cases/{id}/documents",(DeskService s,int id,DocumentInput x,HttpRequest r)=>s.Attach(id,x,Actor(r)));app.MapPost("/api/cases/{id}/submit",(DeskService s,int id,HttpRequest r)=>s.Submit(id,Actor(r)));app.MapPost("/api/cases/{id}/review",(DeskService s,int id,ReviewInput x,HttpRequest r)=>s.Review(id,x,Actor(r)));app.MapPost("/api/cases/{id}/endorse",(DeskService s,int id,HttpRequest r)=>s.Endorse(id,Actor(r)));app.MapPost("/api/cases/{id}/decision",(DeskService s,int id,DecisionInput x,HttpRequest r)=>s.Decide(id,x,Actor(r)));app.MapPost("/api/cases/{id}/schedule",(DeskService s,int id,ScheduleInput x,HttpRequest r)=>s.Schedule(id,x,Actor(r)));app.MapPost("/api/cases/{id}/verify",(DeskService s,int id,VerificationInput x,HttpRequest r)=>s.Verify(id,x,Actor(r)));
if(args.Contains("--initialize")){await using var scope=app.Services.CreateAsyncScope();await using var d=await scope.ServiceProvider.GetRequiredService<IDbContextFactory<DeskDb>>().CreateDbContextAsync();await d.Database.MigrateAsync();await Seed.Run(d);Console.WriteLine("eTulong schema and reference data initialized; existing cases preserved.");return;}app.Run();
sealed class FixedClock(DateOnly date):IClock {public DateOnly Today=>date;public DateTimeOffset Now=>new(date.ToDateTime(new TimeOnly(9,0)),TimeSpan.Zero);}
sealed class WriteFault:IWriteFault {public void AfterWrite(){Console.Error.WriteLine("ETULONG_POST_WRITE_FAULT after actual SaveChanges");throw new Exception("Controlled pre-commit fault");}}
